/**
 * THE PARITY PROOF for bot access (`docs/security/private-repos.md` §22): every `access_notice__*`
 * vector in `forge-contracts/vectors/` (generated by `tools/private-repos-vectors/access.py`), run
 * against `./access-notice` and `lib/rules/agent-request.ts`. forge-core
 * `private::access_conformance` runs the same files with the same input and output shapes.
 */

import { readFileSync, readdirSync } from 'node:fs'
import { resolve } from 'node:path'
import { describe, expect, it } from 'vitest'

import { checkAsk } from '../rules/agent-request'
import type { Role } from '../rules/v2'
import { currentNotices, noticeFromTyped, noticeToTyped, publicLine, type AccessNotice, type NoticeEntry } from './access-notice'
import { bytesToHex, hexToBytes } from './bytes'
import { decodeKeyLetter, encodeKeyLetter, type JsonValue, type TypedLetter } from './key-letter'

type Json = null | boolean | number | string | Json[] | { [k: string]: Json }
type Obj = { readonly [k: string]: Json }

interface Vector {
  readonly name: string
  readonly input: Obj
  readonly expected: Json
}

const VECTORS_DIR = resolve(process.cwd(), '..', 'forge-contracts', 'vectors')
const FILES = readdirSync(VECTORS_DIR)
  .filter((f) => f.startsWith('access_notice__') && f.endsWith('.json'))
  .sort()

const obj = (j: Json | undefined): Obj => j as Obj
const arr = (j: Json | undefined): Json[] => j as Json[]

const typedJson = (t: TypedLetter): Json => ({ type: t.type, v: t.v, fields: t.fields as Json })

function noticeJson(n: AccessNotice): Json {
  return {
    bot: bytesToHex(n.bot),
    may: [...n.may],
    askers: n.askers,
    threads: n.threads === 'all' ? 'all' : [...n.threads],
    processor: n.processor,
    until: n.until,
    revokes: n.revokes.map(bytesToHex),
    note: n.note,
    extra: n.extra as Json,
  }
}

function noticeOf(j: Json | undefined): AccessNotice {
  const o = obj(j)
  return {
    bot: hexToBytes(o.bot as string),
    may: arr(o.may) as string[],
    askers: o.askers === 'writers' ? 'writers' : 'maintainers',
    threads: typeof o.threads === 'string' ? 'all' : (arr(o.threads) as number[]),
    processor: typeof o.processor === 'string' ? o.processor : null,
    until: typeof o.until === 'number' ? o.until : null,
    revokes: arr(o.revokes).map((h) => hexToBytes(h as string)),
    note: o.note as string,
    extra: (o.extra ?? {}) as { [k: string]: JsonValue },
  }
}

function run(i: Obj): Json {
  switch (i.op) {
    case 'noticeFormat': {
      const t = noticeToTyped(noticeOf(i.notice))
      if (t === null) throw new Error('a well-formed notice')
      const pt = encodeKeyLetter(t)
      expect(decodeKeyLetter(pt)).toEqual(t)
      expect(noticeJson(noticeFromTyped(t) as AccessNotice)).toEqual({ ...obj(i.notice), extra: obj(i.notice).extra ?? {} })
      return { letter: typedJson(t), plaintextHex: bytesToHex(pt) }
    }
    case 'noticeDecode':
      return {
        results: arr(i.cases).map((c): Json => {
          const t = decodeKeyLetter(hexToBytes(obj(c).plaintextHex as string))
          if (t === null) return { name: obj(c).name as Json, error: 'malformed' }
          const n = noticeFromTyped(t)
          return { name: obj(c).name as Json, notice: n === null ? null : noticeJson(n) }
        }),
      }
    case 'noticeCurrent': {
      const maintainers = new Set(arr(i.maintainers) as string[])
      const entries: NoticeEntry[] = arr(i.entries).map((e) => ({
        id: obj(e).id as string,
        writer: obj(e).writer as string,
        createdAt: obj(e).createdAt as number,
        packHash: '00'.repeat(32),
        notice: noticeOf(obj(e).notice),
      }))
      const current: { [k: string]: Json } = {}
      for (const [bot, e] of currentNotices(entries, (w) => maintainers.has(w))) current[bot] = e.id
      return { current }
    }
    case 'ask':
      return {
        results: arr(i.cases).map((c) => {
          const o = obj(c)
          const refusal = checkAsk(o.notice === null ? null : noticeOf(o.notice), (o.role ?? null) as Role | null, o.number as number, o.membersOnly === true, o.now as number)
          return { name: o.name as Json, refusal: refusal as Json }
        }),
      }
    default:
      throw new Error(`unknown op ${String(i.op)}`)
  }
}

describe('access notice conformance vectors', () => {
  it('finds them', () => {
    expect(FILES.length).toBeGreaterThanOrEqual(7)
  })
  for (const f of FILES) {
    const v = JSON.parse(readFileSync(resolve(VECTORS_DIR, f), 'utf8')) as Vector
    it(v.name, () => {
      expect(run(v.input)).toEqual(v.expected)
    })
  }
})

describe('the public line', () => {
  const bot = new Uint8Array(32).fill(4)
  const base: AccessNotice = {
    bot,
    may: ['post', 'readOnRequest'],
    askers: 'writers',
    threads: 'all',
    processor: 'Example AI',
    until: Date.UTC(2026, 10, 30),
    revokes: [],
    note: '',
    extra: {},
  }
  it('reads as the design says', () => {
    expect(publicLine(base, '@ci-bot', 0)).toBe(
      "@ci-bot can post here and read pull requests and issues it's asked about. Asked by writers and maintainers. Processed by Example AI. Until 30 Nov 2026.",
    )
  })
  it('names listed threads, maintainers only and no service', () => {
    expect(publicLine({ ...base, may: ['post'], askers: 'maintainers', threads: [42, 57], processor: null, until: null }, '@ci-bot', 0)).toBe(
      '@ci-bot can post here. Asked by maintainers. Only on #42 and #57.',
    )
  })
  it('says when access ended or allows nothing', () => {
    expect(publicLine(base, '@ci-bot', Date.UTC(2026, 11, 1))).toBe("@ci-bot's access ended on 30 Nov 2026.")
    expect(publicLine({ ...base, may: [] }, '@ci-bot', 0)).toBe('@ci-bot has no access here.')
  })
})
